using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.Build;using UnityEditor.Build.Reporting;using UnityEngine.SceneManagement;

public static class MotionProfileAdoption{
 public const string ProfilePath="Assets/CombatPrototype/ApprovedLocomotionProfile.asset";
 const string Menu="Shioka/Developer motion/";
 public static ApprovedLocomotionTuning FindTarget(){var selected=Selection.activeGameObject==null?null:Selection.activeGameObject.GetComponentInParent<ApprovedLocomotionTuning>();return selected!=null?selected:UnityEngine.Object.FindAnyObjectByType<ApprovedLocomotionTuning>(FindObjectsInactive.Include);}
 [MenuItem(Menu+"Select canonical SO")]static void SelectProfile(){var target=FindTarget();Selection.activeObject=target==null?AssetDatabase.LoadAssetAtPath<ApprovedLocomotionProfile>(ProfilePath):target.canonicalProfile;EditorGUIUtility.PingObject(Selection.activeObject);}
 [MenuItem(Menu+"Adopt current runtime draft into canonical SO")]static void Current(){var target=FindTarget();if(target==null){Report(false,"Select the trial fighter");return;}bool ok=TryAdoptCurrent(target,target.canonicalProfile,out var error);Report(ok,error);}
 [MenuItem(Menu+"Adopt current runtime draft into canonical SO",true)]static bool CurrentAvailable()=>EditorApplication.isPlaying&&FindTarget()!=null;
 [MenuItem(Menu+"Adopt saved local JSON into canonical SO")]static void Saved(){var target=FindTarget();if(target==null){Report(false,"Select the trial fighter");return;}bool ok=TryAdoptSaved(target.canonicalProfile,target.SettingsPath,out var error);Report(ok,error);}
 static void Report(bool ok,string error){if(ok)Debug.Log("Motion defaults adopted into the referenced canonical SO. Developer JSON was not changed.");else Debug.LogWarning("Motion adoption refused: "+error);}
 public static bool TryAdoptCurrent(ApprovedLocomotionTuning target,ApprovedLocomotionProfile profile,out string error){error=null;if(!EditorApplication.isPlaying||target==null||!target.DeveloperTuningEnabled){error="Current-draft adoption requires the developer trial in Play mode";return false;}var hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();ApprovedLocomotionSettings value;if(hud!=null&&hud.player==target.Fighter){if(!hud.TryReadMotionDraft(out value,out error)){return false;}}else{value=target.Requested==null?null:target.Requested.Copy();}bool result=TryAdopt(profile,value,out error);return result;}
 public static bool TryAdoptSaved(ApprovedLocomotionProfile profile,string path,out string error){error=null;try{if(!File.Exists(path)){error="No saved draft at "+path;return false;}var value=JsonUtility.FromJson<ApprovedLocomotionSettings>(File.ReadAllText(path));return TryAdopt(profile,value,out error);}catch(Exception ex){error="Saved-draft adoption failed: "+ex.Message;return false;}}
 public static bool TryAdopt(ApprovedLocomotionProfile profile,ApprovedLocomotionSettings value,out string error){error=null;if(profile==null){error="No canonical SO assigned";return false;}if(value==null||!value.Validate(out error)){error=error??"Missing draft";return false;}string path=AssetDatabase.GetAssetPath(profile);if(string.IsNullOrEmpty(path)||!path.StartsWith("Assets/",StringComparison.Ordinal)||!path.EndsWith(".asset",StringComparison.OrdinalIgnoreCase)){error="Target must be a persistent project motion SO";return false;}try{if(!AssetDatabase.IsOpenForEdit(path,StatusQueryOptions.ForceUpdate)||(File.GetAttributes(path)&FileAttributes.ReadOnly)!=0){error="Canonical SO is not writable: "+path;return false;}}catch(Exception ex){error="Canonical access failed: "+ex.Message;return false;}
  string before=EditorJsonUtility.ToJson(profile);try{Undo.RecordObject(profile,"Adopt canonical motion defaults");if(!profile.ReplaceValidated(value,out error))return false;EditorUtility.SetDirty(profile);AssetDatabase.SaveAssetIfDirty(profile);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);var loaded=AssetDatabase.LoadAssetAtPath<ApprovedLocomotionProfile>(path);if(!loaded.TryRead(out var stored,out error)||JsonUtility.ToJson(stored)!=JsonUtility.ToJson(value)){error="Persistence verification failed for "+path;return false;}return true;}catch(Exception ex){EditorJsonUtility.FromJsonOverwrite(before,profile);error="Could not confirm SO adoption: "+ex.Message;return false;}}
 public static bool ValidateBuildTarget(ApprovedLocomotionTuning tuning,out string error){error=null;if(tuning==null||!tuning.TryReadCanonical(out _,out error)){error=error??"Missing tuning consumer";return false;}string path=AssetDatabase.GetAssetPath(tuning.canonicalProfile);if(string.IsNullOrEmpty(path)||path.IndexOf("/Editor/",StringComparison.OrdinalIgnoreCase)>=0){error="Builds require a persistent runtime motion SO, not an Editor-only fixture";return false;}return true;}

}
// Builds consume referenced motion SOs, never developer JSON. Refuse missing/invalid defaults.
public sealed class MotionProfileBuildValidation:IProcessSceneWithReport{
 public int callbackOrder=>0;
 public void OnProcessScene(Scene scene,BuildReport report){if(report==null)return;foreach(var root in scene.GetRootGameObjects())foreach(var tuning in root.GetComponentsInChildren<ApprovedLocomotionTuning>(true)){if(!MotionProfileAdoption.ValidateBuildTarget(tuning,out var error))throw new BuildFailedException("Invalid canonical motion in "+scene.path+": "+error);}}
}
